// tsconfig.json para um projeto Node 24 que roda .ts direto
{
  "compilerOptions": {
    "target": "ES2023",
    "module": "NodeNext",           // segue as regras de módulo do próprio Node
    "moduleResolution": "NodeNext",
    "types": ["node"],              // tipos de process, fs, Buffer...

    "strict": true,                  // null checks, catch como unknown, etc.
    "noUncheckedIndexedAccess": true, // arr[0] e obj[chave] podem ser undefined

    "noEmit": true,                     // o Node roda o .ts; o tsc só checa
    "allowImportingTsExtensions": true, // import './db.ts'
    "erasableSyntaxOnly": true,         // proíbe enum, namespace, parameter properties
    "verbatimModuleSyntax": true,       // obriga `import type` para imports só de tipo

    "skipLibCheck": true
  },
  "include": ["src"]
}

// Vai gerar um build em JS? Troque noEmit/allowImportingTsExtensions por
// "outDir": "dist" e "rewriteRelativeImportExtensions": true.

// Imports relativos levam a extensão .ts: o Node não adivinha extensão
import { createQueue } from './queue.ts';
// import type some na execução (verbatimModuleSyntax exige quando é só tipo)
import type { Job } from 'bullmq';
// Módulos nativos com o prefixo node:
import { readFile } from 'node:fs/promises';
import path from 'node:path';

// __dirname e __filename não existem em ESM. Use import.meta:
const pastaAtual = import.meta.dirname;
console.log(path.basename(import.meta.filename)); // 's3.ts'

// Top-level await: liberado em módulos ESM
const texto = await readFile(path.join(pastaAtual, 'queue.ts'), 'utf8');
console.log(texto.length > 0); // true

// Rodar algo só quando o arquivo é executado direto (não importado)
if (import.meta.main) {
  const fila = createQueue('emails');
  console.log(`fila ${fila.nome} criada`);
}

export function descreverJob(job: Job): string {
  return `${job.name}#${job.id}`;
}

import { z } from 'zod';

// O Node carrega o .env sozinho: node --env-file=.env src/index.ts

const EnvSchema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  PORT: z.coerce.number().int().positive().default(3000), // "3000" → 3000
  REDIS_URL: z.url(),
  LOG_LEVEL: z.enum(['debug', 'info', 'warn', 'error']).default('info'),
});

// Valida UMA vez, na inicialização: config errada e o processo nem sobe
const parsed = EnvSchema.safeParse(process.env);
if (!parsed.success) {
  console.error('Variáveis de ambiente inválidas:\n' + z.prettifyError(parsed.error));
  process.exit(1);
}

export const env = parsed.data;
// env.PORT: number (já convertido), env.NODE_ENV: 'development' | 'test' | 'production'
// No resto do código: import { env } from './env.ts', nunca process.env.ALGO solto
console.log(env.PORT + 1, env.NODE_ENV);

import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { z } from 'zod';

const dataDir = path.join(import.meta.dirname, 'data'); // nunca monte caminhos com '/' na mão

const TarefaSchema = z.object({ id: z.number(), titulo: z.string(), feita: z.boolean() });
type Tarefa = z.infer<typeof TarefaSchema>; // o tipo sai do schema: uma fonte só

async function salvar(tarefas: Tarefa[]): Promise<void> {
  await mkdir(dataDir, { recursive: true });
  await writeFile(path.join(dataDir, 'tarefas.json'), JSON.stringify(tarefas, null, 2));
}

async function carregar(): Promise<Tarefa[]> {
  const texto = await readFile(path.join(dataDir, 'tarefas.json'), 'utf8');
  // JSON.parse devolve any: valide antes de confiar
  return z.array(TarefaSchema).parse(JSON.parse(texto));
}

await salvar([{ id: 1, titulo: 'Estudar filas', feita: false }]);
const tarefas = await carregar();
console.log(tarefas[0]?.titulo);     // 'Estudar filas' (tarefas[0] pode ser undefined)
console.log(await readdir(dataDir)); // [ 'tarefas.json' ]
